package remframework.geometry.discovery;

import org.joml.Vector3d;
import remframework.geometry.discovery.experiment.*;
import remframework.geometry.discovery.realization.session.OrientationConvexityCalculator;
import java.util.*;

/** General normalized face-complex energies and bounded finite-difference gradients. */
public final class DynamicElasticThreeDConstraints {
    private static final double EPS=1e-12;
    private final List<List<Integer>> faces;
    private final ThreeDExperimentConditions modes;
    private final ThreeDConstraintStrengths strengths;
    private final double scale;
    private final Map<Long,List<Integer>> faceEdgeIncidence;
    private final boolean outwardOrientation;
    private final double orientationStrength;
    private final boolean selfIntersectionAvoidance;
    private final double clearance;
    private final double avoidanceStrength;
    private final boolean convexityEnabled;
    private final double convexityTolerance;
    private final double convexityStrength;
    private final Map<String,Double> runtimeFactors;

    public DynamicElasticThreeDConstraints(List<List<Integer>> faces,
            ThreeDExperimentConditions modes,ThreeDConstraintStrengths strengths,double targetEdgeLength){
        this(faces,modes,strengths,targetEdgeLength,false,0,false,0.05,0.6,false,0,0);
    }
    public DynamicElasticThreeDConstraints(List<List<Integer>> faces,ThreeDExperimentConditions modes,ThreeDConstraintStrengths strengths,double targetEdgeLength,boolean outwardOrientation,double orientationStrength){this(faces,modes,strengths,targetEdgeLength,outwardOrientation,orientationStrength,false,.05,.6,false,0,0);}
    public DynamicElasticThreeDConstraints(List<List<Integer>> faces,ThreeDExperimentConditions modes,ThreeDConstraintStrengths strengths,double targetEdgeLength,boolean outwardOrientation,double orientationStrength,boolean selfIntersectionAvoidance,double clearanceFactor,double avoidanceStrength){this(faces,modes,strengths,targetEdgeLength,outwardOrientation,orientationStrength,selfIntersectionAvoidance,clearanceFactor,avoidanceStrength,false,0,0);}
    public DynamicElasticThreeDConstraints(List<List<Integer>> faces,ThreeDExperimentConditions modes,ThreeDConstraintStrengths strengths,double targetEdgeLength,boolean outwardOrientation,double orientationStrength,boolean selfIntersectionAvoidance,double clearanceFactor,double avoidanceStrength,boolean convexityEnabled,double convexityTolerance,double convexityStrength){this(faces,modes,strengths,targetEdgeLength,outwardOrientation,orientationStrength,selfIntersectionAvoidance,clearanceFactor,avoidanceStrength,convexityEnabled,convexityTolerance,convexityStrength,Map.of());}
    public DynamicElasticThreeDConstraints(List<List<Integer>> faces,ThreeDExperimentConditions modes,ThreeDConstraintStrengths strengths,double targetEdgeLength,boolean outwardOrientation,double orientationStrength,boolean selfIntersectionAvoidance,double clearanceFactor,double avoidanceStrength,boolean convexityEnabled,double convexityTolerance,double convexityStrength,Map<String,Double> runtimeFactors){List<List<Integer>> coherent=OrientationConvexityCalculator.coherentFaces(faces);this.faces=(coherent==null?faces:coherent).stream().map(List::copyOf).toList();this.modes=modes;this.strengths=strengths;scale=targetEdgeLength;faceEdgeIncidence=buildIncidence(this.faces);this.outwardOrientation=outwardOrientation;this.orientationStrength=orientationStrength;this.selfIntersectionAvoidance=selfIntersectionAvoidance;this.clearance=Math.max(0,targetEdgeLength*clearanceFactor);this.avoidanceStrength=Math.max(0,avoidanceStrength);this.convexityEnabled=convexityEnabled;this.convexityTolerance=Math.max(0,convexityTolerance);this.convexityStrength=Math.max(0,convexityStrength);this.runtimeFactors=runtimeFactors==null?Map.of():Map.copyOf(runtimeFactors);}

    public void addForces(List<DynamicElasticNode> nodes,Map<Integer,Vector3d> forces){
        if(faces.isEmpty())return;List<Vector3d> p=nodes.stream().map(n->new Vector3d(n.position())).toList();
        double h=Math.max(1e-7,scale*1e-5);
        for(DynamicElasticNode node:nodes){if(node.fixed())continue;Vector3d gradient=new Vector3d();
            for(int axis=0;axis<3;axis++){Vector3d q=p.get(node.id());double old=q.get(axis);q.setComponent(axis,old+h);double plus=energy(p);q.setComponent(axis,old-h);double minus=energy(p);q.setComponent(axis,old);gradient.setComponent(axis,(plus-minus)/(2*h));}
            if(gradient.isFinite())forces.get(node.id()).sub(gradient);
        }
    }

    public ThreeDConstraintDiagnostics diagnostics(List<DynamicElasticNode> nodes){return diagnosticsCoordinates(nodes.stream().map(n->new Vector3d(n.position())).toList());}
    public FaceObjectiveDiagnostics objectiveDiagnostics(List<DynamicElasticNode> nodes){List<Vector3d> p=nodes.stream().map(n->new Vector3d(n.position())).toList();double plan=planarityEnergy(p),angle=angleEnergy(p),dihedral=dihedralValues(p).variance,radius=radiusValues(p).variance/(scale*scale);double pc=modes.facePlanarity()==FacePlanarityMode.REQUIRE_PLANAR_FACES?strengths.facePlanarity()*plan:0,ac=modes.faceAngles()==FaceAngleConditionMode.REQUIRE_EQUAL_ANGLES_WITHIN_EACH_FACE?strengths.faceAngles()*angle:0,dc=modes.dihedrals()==DihedralConditionMode.REQUIRE_EQUAL_DIHEDRAL_ANGLES?strengths.dihedrals()*dihedral:0,rc=modes.facePlaneRadii()==FacePlaneRadiusMode.REQUIRE_EQUAL_FACE_PLANE_RADII?strengths.facePlaneRadii()*radius:0;ThreeDConstraintDiagnostics d=diagnosticsCoordinates(p);return new FaceObjectiveDiagnostics(d.maximumFacePlanarityError(),Math.sqrt(plan)*scale,d.maximumFaceAngleDeviation(),Math.sqrt(angle),pc,ac,dc,rc,pc+ac+dc+rc);}

    private double energy(List<Vector3d> p){double value=0;
        if(modes.facePlanarity()==FacePlanarityMode.REQUIRE_PLANAR_FACES)value+=strengths.facePlanarity()*factor("FACE_PLANARITY")*DevelopmentTimingDiagnostics.measure("stage2.face-planarity-objective",()->planarityEnergy(p));
        if(modes.faceAngles()==FaceAngleConditionMode.REQUIRE_EQUAL_ANGLES_WITHIN_EACH_FACE)value+=strengths.faceAngles()*factor("FACE_ANGLE")*DevelopmentTimingDiagnostics.measure("stage2.face-angle-objective",()->angleEnergy(p));
        if(modes.dihedrals()==DihedralConditionMode.REQUIRE_EQUAL_DIHEDRAL_ANGLES)value+=strengths.dihedrals()*factor("DIHEDRAL_ANGLE")*DevelopmentTimingDiagnostics.measure("stage2.dihedral-objective",()->dihedralValues(p).variance);
        if(modes.facePlaneRadii()==FacePlaneRadiusMode.REQUIRE_EQUAL_FACE_PLANE_RADII)value+=strengths.facePlaneRadii()*factor("FACE_DISTANCE")*DevelopmentTimingDiagnostics.measure("stage2.face-plane-radius-objective",()->radiusValues(p).variance)/(scale*scale);
        if(outwardOrientation)value+=orientationStrength*factor("FACE_ORIENTATION")*orientationEnergy(p);
        if(selfIntersectionAvoidance)value+=avoidanceStrength*factor("SELF_INTERSECTION_AVOIDANCE")*avoidanceEnergy(p);
        if(convexityEnabled)value+=convexityStrength*factor("CONVEXITY")*convexityEnergy(p);
        return value;
    }
    private double convexityEnergy(List<Vector3d> p){if(faces.isEmpty()||p.isEmpty())return 0;List<Plane> planes=faces.stream().map(f->plane(f,p)).toList();if(planes.stream().anyMatch(Objects::isNull))return 0;Vector3d center=new Vector3d();p.forEach(center::add);center.div(p.size());double signed=planes.stream().mapToDouble(x->x.normal.dot(new Vector3d(x.point).sub(center))).sum();double orientation=signed<0?-1:1;double sum=0;int count=0;for(Plane face:planes)for(int id=0;id<p.size();id++)if(!face.vertices.contains(id)){double h=orientation*face.normal.dot(new Vector3d(p.get(id)).sub(face.point));double violation=Math.max(0,h-convexityTolerance)/scale;sum+=violation*violation;count++;}return count==0?0:sum/count;}
    public double convexityObjective(List<DynamicElasticNode> nodes){return convexityEnergy(nodes.stream().map(n->new Vector3d(n.position())).toList());}
    private double avoidanceEnergy(List<Vector3d> p){double sum=0;for(Pair pair:applicablePairs()){double d=pair.distance(p);if(d<clearance){double e=clearance-d;sum+=e*e;}}return sum;}
    public SelfIntersectionDiagnostics selfIntersectionDiagnostics(List<DynamicElasticNode> nodes){if(!selfIntersectionAvoidance)return SelfIntersectionDiagnostics.inactive();List<Vector3d> p=nodes.stream().map(n->new Vector3d(n.position())).toList();int facesCrossing=0,trianglesCrossing=0,coplanar=0,near=0;double min=Double.POSITIVE_INFINITY,maxPen=0,sum=0;for(Pair pair:applicablePairs()){double d=pair.distance(p);min=Math.min(min,d);if(pair.intersects(p)){facesCrossing++;trianglesCrossing++;if(pair.coplanar(p))coplanar++;}if(d<clearance&&!pair.intersects(p))near++;double e=Math.max(0,clearance-d);maxPen=Math.max(maxPen,e);sum+=e*e;}return new SelfIntersectionDiagnostics(facesCrossing,trianglesCrossing,coplanar,near,min,maxPen,Math.sqrt(sum/Math.max(1,applicablePairs().size())),avoidanceStrength*sum,Double.isFinite(sum));}
    private List<Pair> applicablePairs(){List<Pair> result=new ArrayList<>();for(int a=0;a<faces.size();a++)for(int b=a+1;b<faces.size();b++){Set<Integer> va=new HashSet<>(faces.get(a));Set<Integer> vb=new HashSet<>(faces.get(b));if(!Collections.disjoint(va,vb))continue;List<Integer> fa=faces.get(a),fb=faces.get(b);for(int i=1;i+1<fa.size();i++)for(int j=1;j+1<fb.size();j++)result.add(new Pair(a,b,fa.get(0),fa.get(i),fa.get(i+1),fb.get(0),fb.get(j),fb.get(j+1)));}return result;}
    private double orientationEnergy(List<Vector3d> p){Vector3d center=new Vector3d();p.forEach(center::add);center.div(p.size());List<Plane> planes=faces.stream().map(f->plane(f,p)).toList();double sign=planes.stream().mapToDouble(x->x.normal.dot(new Vector3d(x.point).sub(center))).sum()<0?-1:1;double sum=0;int count=0;for(Plane plane:planes){Vector3d radial=new Vector3d(plane.point).sub(center);if(radial.lengthSquared()<=EPS)continue;double alignment=sign*plane.normal.dot(radial.normalize());double error=Math.max(0,-alignment);sum+=error*error;count++;}return count==0?0:sum/count;}
    private double planarityEnergy(List<Vector3d> p){double sum=0;int count=0;for(List<Integer> f:faces){Plane plane=plane(f,p);for(int id:f){double d=Math.abs(new Vector3d(p.get(id)).sub(plane.point).dot(plane.normal))/scale;sum+=d*d;count++;}}return count==0?0:sum/count;}
    private double angleEnergy(List<Vector3d> p){double sum=0;int count=0;for(List<Integer> f:faces){double target=(f.size()-2.0)*Math.PI/f.size();for(int i=0;i<f.size();i++){Vector3d a=new Vector3d(p.get(f.get((i-1+f.size())%f.size()))).sub(p.get(f.get(i)));Vector3d b=new Vector3d(p.get(f.get((i+1)%f.size()))).sub(p.get(f.get(i)));if(a.lengthSquared()>EPS&&b.lengthSquared()>EPS){double angle=Math.acos(clamp(a.normalize().dot(b.normalize())));double d=angle-target;sum+=d*d;count++;}}}return count==0?0:sum/count;}
    private Values dihedralValues(List<Vector3d> p){List<Double> values=new ArrayList<>();for(var e:faceEdgeIncidence.entrySet())if(e.getValue().size()==2){Vector3d a=plane(faces.get(e.getValue().get(0)),p).normal,b=plane(faces.get(e.getValue().get(1)),p).normal;double raw=Math.acos(clamp(Math.abs(a.dot(b))));values.add(raw);}return values(values);}
    private Values radiusValues(List<Vector3d> p){Vector3d center=new Vector3d();p.forEach(center::add);center.div(p.size());List<Double> values=new ArrayList<>();for(List<Integer> f:faces){Plane plane=plane(f,p);values.add(Math.abs(new Vector3d(center).sub(plane.point).dot(plane.normal)));}return values(values);}
    private ThreeDConstraintDiagnostics diagnosticsCoordinates(List<Vector3d> p){double planar=0,angle=0;for(List<Integer> f:faces){Plane plane=plane(f,p);double target=(f.size()-2.0)*Math.PI/f.size();for(int i=0;i<f.size();i++){planar=Math.max(planar,Math.abs(new Vector3d(p.get(f.get(i))).sub(plane.point).dot(plane.normal)));Vector3d a=new Vector3d(p.get(f.get((i-1+f.size())%f.size()))).sub(p.get(f.get(i))),b=new Vector3d(p.get(f.get((i+1)%f.size()))).sub(p.get(f.get(i)));if(a.lengthSquared()>EPS&&b.lengthSquared()>EPS)angle=Math.max(angle,Math.abs(Math.acos(clamp(a.normalize().dot(b.normalize())))-target));}}
        Values d=dihedralValues(p),r=radiusValues(p);double volume=volume(p);boolean manifold=faceEdgeIncidence.values().stream().allMatch(x->x.size()==2);return new ThreeDConstraintDiagnostics(planar,angle,d.maxDeviation,d.variance,r.maxDeviation,r.variance,volume,manifold,Double.isFinite(planar+angle+d.variance+r.variance+volume));}
    private double volume(List<Vector3d> p){Vector3d center=new Vector3d();p.forEach(center::add);center.div(p.size());double sum=0;for(List<Integer> f:faces){List<Integer> ordered=new ArrayList<>(f);Plane plane=plane(f,p);Vector3d fc=plane.point;if(plane.normal.dot(new Vector3d(fc).sub(center))<0)Collections.reverse(ordered);Vector3d a=p.get(ordered.get(0));for(int i=1;i+1<ordered.size();i++)sum+=a.dot(new Vector3d(p.get(ordered.get(i))).cross(p.get(ordered.get(i+1))))/6;}return Math.abs(sum);}
    private Plane plane(List<Integer> f,List<Vector3d> p){Vector3d center=new Vector3d();for(int id:f)center.add(p.get(id));center.div(f.size());Vector3d n=new Vector3d();for(int i=0;i<f.size();i++){Vector3d a=p.get(f.get(i)),b=p.get(f.get((i+1)%f.size()));n.x+=(a.y-b.y)*(a.z+b.z);n.y+=(a.z-b.z)*(a.x+b.x);n.z+=(a.x-b.x)*(a.y+b.y);}if(n.lengthSquared()<=EPS){for(int i=1;i+1<f.size();i++){n.set(p.get(f.get(i))).sub(p.get(f.get(0))).cross(new Vector3d(p.get(f.get(i+1))).sub(p.get(f.get(0))));if(n.lengthSquared()>EPS)break;}}if(n.lengthSquared()<=EPS)n.set(0,0,1);else n.normalize();return new Plane(center,n,Set.copyOf(f));}
    private static Map<Long,List<Integer>> buildIncidence(List<List<Integer>> faces){Map<Long,List<Integer>> result=new HashMap<>();for(int fi=0;fi<faces.size();fi++){List<Integer> face=faces.get(fi);for(int i=0;i<face.size();i++)result.computeIfAbsent(key(face.get(i),face.get((i+1)%face.size())),ignored->new ArrayList<>()).add(fi);}Map<Long,List<Integer>> immutable=new HashMap<>();result.forEach((key,value)->immutable.put(key,List.copyOf(value)));return Map.copyOf(immutable);}
    private static Values values(List<Double> v){if(v.isEmpty())return new Values(0,0);double mean=v.stream().mapToDouble(Double::doubleValue).average().orElse(0),variance=v.stream().mapToDouble(x->{double d=x-mean;return d*d;}).average().orElse(0),max=v.stream().mapToDouble(x->Math.abs(x-mean)).max().orElse(0);return new Values(variance,max);}
    private static long key(int a,int b){return ((long)Math.min(a,b)<<32)|(Math.max(a,b)&0xffffffffL);}
    private static double clamp(double x){return Math.max(-1,Math.min(1,x));}
    private double factor(String constraintId){return runtimeFactors.getOrDefault(constraintId,1.0);}
    private record Plane(Vector3d point,Vector3d normal,Set<Integer> vertices){ }
    private record Pair(int faceA,int faceB,int a0,int a1,int a2,int b0,int b1,int b2){
        double distance(List<Vector3d> p){Vector3d[] a={p.get(a0),p.get(a1),p.get(a2)},b={p.get(b0),p.get(b1),p.get(b2)};double d=Double.POSITIVE_INFINITY;for(Vector3d v:a)d=Math.min(d,pointTriangle(v,b));for(Vector3d v:b)d=Math.min(d,pointTriangle(v,a));for(int i=0;i<3;i++)for(int j=0;j<3;j++)d=Math.min(d,segmentDistance(a[i],a[(i+1)%3],b[j],b[(j+1)%3]));return intersects(p)?0:d;}
        boolean intersects(List<Vector3d> p){Vector3d[] a={p.get(a0),p.get(a1),p.get(a2)},b={p.get(b0),p.get(b1),p.get(b2)};if(coplanar(p))return coplanarOverlap(a,b);for(int i=0;i<3;i++)if(segmentTriangle(a[i],a[(i+1)%3],b))return true;for(int i=0;i<3;i++)if(segmentTriangle(b[i],b[(i+1)%3],a))return true;return pointTriangle(a[0],b)<1e-9&&pointInTriangle(a[0],b);}
        boolean coplanar(List<Vector3d> p){Vector3d n=new Vector3d(p.get(a1)).sub(p.get(a0)).cross(new Vector3d(p.get(a2)).sub(p.get(a0)));Vector3d m=new Vector3d(p.get(b1)).sub(p.get(b0)).cross(new Vector3d(p.get(b2)).sub(p.get(b0)));return n.lengthSquared()>EPS&&m.lengthSquared()>EPS&&n.normalize().dot(m.normalize())>.999999&&Math.abs(new Vector3d(p.get(b0)).sub(p.get(a0)).dot(n.normalize()))<1e-8;}
    }
    private static boolean coplanarOverlap(Vector3d[] a,Vector3d[] b){int drop=0;Vector3d n=new Vector3d(a[1]).sub(a[0]).cross(new Vector3d(a[2]).sub(a[0]));if(Math.abs(n.y)>Math.abs(n.x)&&Math.abs(n.y)>=Math.abs(n.z))drop=1;else if(Math.abs(n.z)>Math.abs(n.x))drop=2;for(int i=0;i<3;i++)for(int j=0;j<3;j++)if(segment2d(a[i],a[(i+1)%3],b[j],b[(j+1)%3],drop))return true;return pointIn2d(a[0],b,drop)||pointIn2d(b[0],a,drop);}
    private static boolean segment2d(Vector3d a,Vector3d b,Vector3d c,Vector3d d,int drop){double ax=coord(a,drop,0),ay=coord(a,drop,1),bx=coord(b,drop,0),by=coord(b,drop,1),cx=coord(c,drop,0),cy=coord(c,drop,1),dx=coord(d,drop,0),dy=coord(d,drop,1);double o1=(bx-ax)*(cy-ay)-(by-ay)*(cx-ax),o2=(bx-ax)*(dy-ay)-(by-ay)*(dx-ax),o3=(dx-cx)*(ay-cy)-(dy-cy)*(ax-cx),o4=(dx-cx)*(by-cy)-(dy-cy)*(bx-cx);return o1*o2<=1e-12&&o3*o4<=1e-12&&Math.max(Math.min(ax,bx),Math.min(cx,dx))<=Math.min(Math.max(ax,bx),Math.max(cx,dx))+1e-10&&Math.max(Math.min(ay,by),Math.min(cy,dy))<=Math.min(Math.max(ay,by),Math.max(cy,dy))+1e-10;}
    private static boolean pointIn2d(Vector3d p,Vector3d[] t,int drop){int sign=0;for(int i=0;i<3;i++){double cross=(coord(t[(i+1)%3],drop,0)-coord(t[i],drop,0))*(coord(p,drop,1)-coord(t[i],drop,1))-(coord(t[(i+1)%3],drop,1)-coord(t[i],drop,1))*(coord(p,drop,0)-coord(t[i],drop,0));if(Math.abs(cross)>1e-10){int s=cross>0?1:-1;if(sign!=0&&sign!=s)return false;sign=s;}}return true;}
    private static double coord(Vector3d v,int drop,int axis){if(drop==0)return axis==0?v.y:v.z;if(drop==1)return axis==0?v.x:v.z;return axis==0?v.x:v.y;}
    private static double pointTriangle(Vector3d p,Vector3d[] t){Vector3d n=new Vector3d(t[1]).sub(t[0]).cross(new Vector3d(t[2]).sub(t[0]));double len=n.length();if(len<EPS)return Math.min(p.distance(t[0]),Math.min(p.distance(t[1]),p.distance(t[2])));n.div(len);double plane=Math.abs(new Vector3d(p).sub(t[0]).dot(n));return plane;}
    private static boolean pointInTriangle(Vector3d p,Vector3d[] t){Vector3d n=new Vector3d(t[1]).sub(t[0]).cross(new Vector3d(t[2]).sub(t[0])).normalize();double s1=new Vector3d(t[1]).sub(t[0]).cross(new Vector3d(p).sub(t[0])).dot(n),s2=new Vector3d(t[2]).sub(t[1]).cross(new Vector3d(p).sub(t[1])).dot(n),s3=new Vector3d(t[0]).sub(t[2]).cross(new Vector3d(p).sub(t[2])).dot(n);return s1>=-1e-9&&s2>=-1e-9&&s3>=-1e-9;}
    private static boolean segmentTriangle(Vector3d a,Vector3d b,Vector3d[] t){Vector3d n=new Vector3d(t[1]).sub(t[0]).cross(new Vector3d(t[2]).sub(t[0]));double da=new Vector3d(a).sub(t[0]).dot(n),db=new Vector3d(b).sub(t[0]).dot(n);if(da*db>0||Math.abs(da-db)<EPS)return false;double u=da/(da-db);return pointInTriangle(new Vector3d(a).lerp(b,u),t);}
    private static double segmentDistance(Vector3d a,Vector3d b,Vector3d c,Vector3d d){double best=Math.min(pointSegment(a,c,d),pointSegment(b,c,d));best=Math.min(best,pointSegment(c,a,b));return Math.min(best,pointSegment(d,a,b));}
    private static double pointSegment(Vector3d p,Vector3d a,Vector3d b){Vector3d ab=new Vector3d(b).sub(a);double t=Math.max(0,Math.min(1,new Vector3d(p).sub(a).dot(ab)/Math.max(EPS,ab.lengthSquared())));return p.distance(new Vector3d(a).fma(t,ab));}
    private record Values(double variance,double maxDeviation){}
}
